mapper.select:
SELECT r.room_no, r.user_no, r.admin_no, r.status, r.category, r.last_message, r.last_message_date, r.created_date, r.closed_date, ( SELECT COUNT(*) FROM chat_message m WHERE m.room_no = r.room_no AND m.sender_no IS NOT NULL AND m.sender_no != #{viewerNo, jdbcType=NUMERIC} AND m.read_yn = 'N' ) AS unread_count FROM chat_room r WHERE 1 = 1
AND r.status = #{status, jdbcType=VARCHAR}
AND r.category = #{category, jdbcType=VARCHAR}
AND ( TO_CHAR(r.room_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR TO_CHAR(r.user_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR TO_CHAR(r.admin_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR LOWER(r.last_message) LIKE '%' || LOWER(#{keyword, jdbcType=VARCHAR}) || '%' )
ORDER BY CASE r.status WHEN 'OPEN' THEN 1 WHEN 'CLOSED' THEN 2 ELSE 3 END, r.last_message_date DESC NULLS LAST, r.created_date DESC
OFFSET #{offset, jdbcType=NUMERIC} ROWS FETCH NEXT #{size, jdbcType=NUMERIC} ROWS ONLY

SELECT COUNT(*) FROM chat_room r WHERE 1 = 1
AND r.status = #{status, jdbcType=VARCHAR}
AND r.category = #{category, jdbcType=VARCHAR}
AND ( TO_CHAR(r.room_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR TO_CHAR(r.user_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR TO_CHAR(r.admin_no) LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR LOWER(r.last_message) LIKE '%' || LOWER(#{keyword, jdbcType=VARCHAR}) || '%' )

mapper.update:
UPDATE chat_room
SET category = #{category, jdbcType=VARCHAR}
WHERE room_no = #{roomNo, jdbcType=NUMERIC}
AND status = 'OPEN'

mapper.delete:
DELETE FROM chat_room
WHERE room_no = #{roomNo, jdbcType=NUMERIC}
AND status = 'CLOSED'

mapper.update:
UPDATE chat_room
SET admin_no = #{adminNo, jdbcType=NUMERIC}
WHERE room_no = #{roomNo, jdbcType=NUMERIC}
AND admin_no IS NULL
AND status = 'OPEN'

UPDATE chat_message
SET read_yn = 'Y'
WHERE room_no = #{roomNo, jdbcType=NUMERIC}
AND sender_no IS NOT NULL
AND sender_no != #{viewerNo, jdbcType=NUMERIC}
AND read_yn = 'N'
